    "description": "36氪获悉，天眼查App显示，近日，广东新型储能国家研究院有限公司发生工商变更，新增宁德时代新能源科技股份有限公司、上海电气集团输配电装备有限公司等为股东，同时，注册资本由2亿元人民币增至约2.9亿元人民币。该公司成立于2023年4月，法定代表人为姜海龙，经营范围包括新材料技术研发、新兴能源技术研发、在线能源计量技术研发等，现由中国大唐集团科学技术研究总院有限公司、北京中科海钠科技有限责任公司及上述新增股东等共同持股。",
    "content": "36氪获悉，天眼查App显示，近日，广东新型储能国家研究院有限公司发生工商变更，新增宁德时代新能源科技股份有限公司、上海电气集团输配电装备有限公司等为股东，同时，注册资本由2亿元人民币增至约2.9亿元人民币。该公司成立于2023年4月，法定代表人为姜海龙，经营范围包括新材料技术研发、新兴能源技术研发、在线能源计量技术研发等，现由中国大唐集团科学技术研究总院有限公司、北京中科海钠科技有限责任公司及上述新增股东等共同持股。"
