    "content": "中新网北京10月23日电 (记者 陈康亮)据中国证监会23日消息，为进一步规范私募投资母基金业务活动，促进私募投资母基金规范健康发展，证监会根据《中华人民共和国证券投资基金法》《私募投资基金监督管理条例》(下称《私募条例》)等法律法规，起草了《私募投资母基金管理规定》(下称《母基金规定》)征求意见稿，向社会公开征求意见。"
