    "description": "中新网海口10月23日电 (记者 王晓斌)23日在海南省非物质文化遗产展示中心，深沉悠远的阿尔卑斯长号与清脆空灵的黎族鼻箫交替响起。正在海南开展文化交流的瑞士日内瓦州立管乐团与海南本土乐师面对面互动：瑞士乐手带来萨克斯与超长阿尔卑斯长号的演奏，海南乐者则献上鼻箫、叮咚及竹竿舞，以各自独特的音乐语言展开文化对话。",
