    "title": "佰维存储：积极拓展人工智能算力基础设施等新兴应用市场",
    "link": "https://36kr.com/newsflashes/4038307430405000?f=rss",
    "pub_date": "2026-10-23 18:18:45",
    "author": "",
    "description": "36氪获悉，佰维存储公告，公司持续推进“存储+晶圆级先进封测”双轮驱动战略，加快晶圆级先进封测制造项目建设。公司围绕先进存储、存算合封及高速光电互联等领域，持续推进FOMS、CMC、OEC等先进封装技术研发及产业化应用，积极拓展人工智能算力基础设施等新兴应用市场，为公司中长期发展培育新的增长动能。公司看好人工智能产业发展带来的中长期存储市场机遇，将持续发挥在存储解决方案、芯片设计及先进封装测试等领域的技术积累和产业协同优势，积极把握行业…",
