    "pub_date": "2026-10-23 18:10:19",
    "author": "",
    "description": "36氪获悉，上交所消息，2026年10月19日至2026年10月23日，上交所公司监管部门共发送监管工作函11份；通过事中事后监管，要求上市公司披露补充、更正类公告5份。所对128起拉抬打压、虚假申报等证券异常交易行为采取了自律监管措施，对26起上市公司重大事项等进行专项核查，向证监会上报涉嫌违法违规案件线索1起。",
    "content": "36氪获悉，上交所消息，2026年10月19日至2026年10月23日，上交所公司监管部门共发送监管工作函11份；通过事中事后监管，要求上市公司披露补充、更正类公告5份。所对128起拉抬打压、虚假申报等证券异常交易行为采取了自律监管措施，对26起上市公司重大事项等进行专项核查，向证监会上报涉嫌违法违规案件线索1起。"
