    "description": "36氪获悉，中央网络安全和信息化委员会印发《国家信息化“十五五”规划》。其中指出，完善一体化应用基础设施。实施国家区块链网络建设工程，夯实价值互联网基础。加快构建全国一体化算力网，推动算力、电力、网络协同发展。优化通用算力、智能算力、超级算力布局。探索太空算力前瞻研究和技术布局。稳妥建设数据流通利用基础设施。打造新型工业网络，推动移动物联网自主迭代。建设新型广电网络。推进交通、能源、市政、水利等基础设施数智化升级。",
    "content": "36氪获悉，中央网络安全和信息化委员会印发《国家信息化“十五五”规划》。其中指出，完善一体化应用基础设施。实施国家区块链网络建设工程，夯实价值互联网基础。加快构建全国一体化算力网，推动算力、电力、网络协同发展。优化通用算力、智能算力、超级算力布局。探索太空算力前瞻研究和技术布局。稳妥建设数据流通利用基础设施。打造新型工业网络，推动移动物联网自主迭代。建设新型广电网络。推进交通、能源、市政、水利等基础设施数智化升级。"
