    "content": "IT之家 10 月 23 日消息，据河南广播电视台旗下大象新闻报道，近期河南省儿童医院眼科接诊了一名 3 岁患儿，其双眼近视已超过 500 度。IT之家参考报道获悉， 该患儿近视原因是“父母平时较忙”，因此使用手机充当“电子保姆”，孩子每天使用手机超过 5 至 6 小时 。 公开信息显示，近视会导致眼睛视物模糊、干涩、疲劳，还可能引起注意力不集中、头晕等不适，影响孩子的正常学习、生活和身心健康。有些专业和工作对视力有严格要求，近视也有可能影响未来的择业选择。 河南省儿童医院眼科副主任医师楚瑞雪称，这种情况不去干预会…"
