    "content": "1956年，达特茅斯会议为“人工智能”这一研究领域命名。70年后，当AI已经从实验室走向千行百业，一个新的问题摆在研究者面前：如果机器真的能够学习、推理、写代码，甚至参与科学发现，那么未来十年，人工智能还将走向哪里？ 在ICAAS 2026首场圆桌对话中，诺贝尔化学奖得主、斯坦福大学教授迈克尔·莱维特，2021年图灵奖得主杰克·唐加拉，以及数学家马骁、中关村学院何纪言，围绕AI的技术路线、产业价值、研究方法和自我进化展开了一场跨越计算机科学、数学与自然科学的讨论。 他们的背景不同，对未来的判断也并不完全一致。但这些…"
