    "description": "上周周五晚上回老家，周六和周日和老妈待两天，遇上下雨天，除了做一日三餐，白天确实没有啥事可做。 没事可做，就和老妈一起看电视。 我们家里的电视机，一年开不了三次。 划拉着电视，偶尔碰到电视连续剧《雷雨》，连着刷两集，还意犹未尽。 这才是我喜欢的电视剧类型啊，熬夜也得看。",
    "content": "上周周五晚上回老家，周六和周日和老妈待两天，遇上下雨天，除了做一日三餐，白天确实没有啥事可做。 没事可做，就和老妈一起看电视。 老妈看的是《父母爱情》，我跟着看了两三集。 剧中大部分都是资深演员，父亲郭涛演的，母亲是梅婷演的。 老年父亲的演员还行，老年母亲的演员感觉太年轻了，演八十多岁的母亲，看她的脸部皮肤那么紧致，只是头发染成白色的，怎么都没有代入感。 我们家里的电视机，一年开不了三次。 老妈说电器东西要常开，我也可以在家里追这部剧。 可我总觉得没有这么多时间用来追剧。 划拉着电视，偶尔碰到电视连续剧《雷雨》，连…"
