    "content": "10月22日，科大讯飞披露最新开发者生态数据。目前讯飞开放平台开发者总数已经达到1187万，2026年大模型相关企业开发者同比增长超过104%。此外，按照讯飞以单次调用互动数超过1万衡量复杂任务的口径，平台上使用大模型处理复杂任务的用户占比，已经从此前不足10%快速提升至60%。 这意味着，现在企业开始把长链路、多任务和复杂上下文工作交给Agent，希望它能够真正进入业务流程并持续执行。 围绕这一变化，讯飞此次一口气推出和升级了几套彼此衔接的体系：星辰TaaS负责把底层模型和Token组织成可交付的行业方案；Age…"
