    "pub_date": "2026-10-23 17:36:44",
    "author": "",
    "description": "中新网10月23日电 据“证监会发布”微信公众号消息，为进一步规范私募投资母基金业务活动，促进私募投资母基金规范健康发展，中国证监会根据《中华人民共和国证券投资基金法》《私募投资基金监督管理条例》(以下简称《私募条例》)等法律法规，起草了《私募投资母基金管理规定》(以下简称《母基金规定》)征求意见稿，现向社会公开征求意见。",
