    "content": "新华社北京10月23日电（记者邵艺博、孙楠）10月25日是新中国恢复联合国合法席位55周年纪念日。外交部发言人毛宁23日在例行记者会上表示，55年来，中国坚持做世界和平的建设者、全球发展的贡献者、国际秩序的维护者。站在新的历史起点上，中国将继续发挥负责任大国作用，持续深化同联合国全方位合作。 毛宁表示，1971年10月25日，第26届联大以压倒性多数通过第2758号决议，决定恢复中华人民共和国在联合国的一切权利。这标志着占世界人口四分之一的中国人民重返联合国舞台，对中国、对世界、对联合国都具有重大而深远的意义。“中…"
