    "author": "",
    "description": "新华社西藏巴青10月23日电（记者翟永冠、格桑朗杰）10月23日，记者从西藏那曲市人民政府新闻办召开的新闻发布会上了解到，西藏巴青震区平均海拔接近4800米，环境高寒缺氧，次生灾害隐患与余震叠加风险仍存，救援队伍将持续做好防范措施，克服难点开展震区救援工作。 据介绍，震区夜间气温低，加上地震扰动山体，滑坡、崩塌、滚石是当前最主要的次生灾害风险；余震叠加效应可能对已受损建筑造成进一步破坏，存在建筑倒塌风险；此外，后续可能出现分散性阵雪，高…",
    "content": "新华社西藏巴青10月23日电（记者翟永冠、格桑朗杰）10月23日，记者从西藏那曲市人民政府新闻办召开的新闻发布会上了解到，西藏巴青震区平均海拔接近4800米，环境高寒缺氧，次生灾害隐患与余震叠加风险仍存，救援队伍将持续做好防范措施，克服难点开展震区救援工作。 据介绍，震区夜间气温低，加上地震扰动山体，滑坡、崩塌、滚石是当前最主要的次生灾害风险；余震叠加效应可能对已受损建筑造成进一步破坏，存在建筑倒塌风险；此外，后续可能出现分散性阵雪，高海拔阴坡路段易出现积雪、暗冰，救灾车辆需注意行车安全。 那曲市应急管理局党委书记…"
