    "description": "新华社北京10月23日电 题：世界雪豹日：守护正扩大的雪豹版图 新华社记者黄垚 10月23日是世界雪豹日。记者从国家林草局获悉，自2013年系统性开展雪豹专项保护工作以来，我国持续加强雪豹保护及其栖息地修复。目前，我国雪豹种群数量已由2013年约2500只增至约5000只，实现倍增。 雪豹是国家一级保护野生动物、全球高山生态系统的旗舰物种和伞护物种，被誉为“雪山之王”，是衡量高寒山地生态系统完整、稳定与健康的核心指示性物种。 我国是全球…",
    "content": "新华社北京10月23日电 题：世界雪豹日：守护正扩大的雪豹版图 新华社记者黄垚 10月23日是世界雪豹日。记者从国家林草局获悉，自2013年系统性开展雪豹专项保护工作以来，我国持续加强雪豹保护及其栖息地修复。目前，我国雪豹种群数量已由2013年约2500只增至约5000只，实现倍增。 雪豹是国家一级保护野生动物、全球高山生态系统的旗舰物种和伞护物种，被誉为“雪山之王”，是衡量高寒山地生态系统完整、稳定与健康的核心指示性物种。 我国是全球雪豹分布最广、种群数量最多、栖息地面积最大的国家，栖息地总面积约208万平方公里…"
