    "content": "日前（10月17日），上海演艺集团在上海大歌剧院镜厅宣告正式挂牌成立。镜厅顶天立地的窗外是浩浩荡荡日夜奔流不息的黄浦江，给人以无限遐想。 习近平总书记考察上海时，殷殷嘱托，期待上海打造具有世界影响力的文化品牌。落实中央号召，上海市委确立了打造全国领先、具有世界影响力的演艺“航空母舰”的目标。 这需要有战略性思考和改革。近年来，大家一直都在期待这一宏伟蓝图落地，成为美好现实。现在，我们终于看到，上海演艺集团，这艘文化航母汽笛长鸣，拔锚起航，向着广阔的文化蓝海挺进！ 这不仅是上海文化发展史上的大事，也是引起全国文艺界广…"
