    "content": "据法治日报报道，今年1月，顾客滕某前往新疆奎屯一家美发屋理发，洗头后突然倒地，生命垂危。店员第一时间拨120、报警，并在等待救援时掐人中应急施救；店主随后联系附近医护接力抢救。遗憾的是，滕某最终经抢救无效死亡。家属将美发屋告上法庭，索赔46万余元，理由包括“没等顾客适应温差”“施救方式错误加重伤情”。 7月6日，一审法院判决驳回滕某家属的全部诉讼请求。9月22日，二审法院判决驳回原告上诉，维持原判。 一审法院认为：洗头是正常服务，滕某突发疾病不可预见；店员已及时报警呼救，掐人中虽不专业，但属于紧急情况下的善意处置，…"
