    "title": "前9个月我国造船三大指标全面增长",
    "link": "http://www.news.cn/20261023/80a0af71966c4bff8b9487d0656057eb/c.html",
    "pub_date": "2026-10-23 17:05:32",
    "author": "",
    "description": "新华社北京10月23日电 工业和信息化部23日发布的数据显示，今年前9个月，我国造船三大指标全面增长，国际市场份额保持全球领先。 数据显示，前9个月，我国造船完工量5805万载重吨，同比增长50.7%，占世界总量的63.6%；新接订单量17529万载重吨，同比增长163.2%，占世界总量的81.8%。截至9月底，手持订单量39913万载重吨，同比增长64.8%，占世界总量的72.4%。",
    "content": "新华社北京10月23日电 工业和信息化部23日发布的数据显示，今年前9个月，我国造船三大指标全面增长，国际市场份额保持全球领先。 数据显示，前9个月，我国造船完工量5805万载重吨，同比增长50.7%，占世界总量的63.6%；新接订单量17529万载重吨，同比增长163.2%，占世界总量的81.8%。截至9月底，手持订单量39913万载重吨，同比增长64.8%，占世界总量的72.4%。"
