    "author": "",
    "description": "记者从最高人民检察院10月23日举行的新闻发布会获悉，检察机关坚持加强对涉工伤、养老、医疗、拆迁、拆违等涉及群众切身利益案件的行政生效裁判监督，两年来办理工伤认定及赔偿、工龄漏算、养老金补发等社保领域案件2600余件，办理征收拆迁领域行政补偿、赔偿案件8700余件，并且围绕残疾人、老年人、妇女、军人军属等特定群体，加大权益保护力度。 行政生效裁判监督是行政诉讼监督的重要职能之一。最高检于2024年10月部署开展行政生效裁判监督专项活动。…",
    "content": "记者从最高人民检察院10月23日举行的新闻发布会获悉，检察机关坚持加强对涉工伤、养老、医疗、拆迁、拆违等涉及群众切身利益案件的行政生效裁判监督，两年来办理工伤认定及赔偿、工龄漏算、养老金补发等社保领域案件2600余件，办理征收拆迁领域行政补偿、赔偿案件8700余件，并且围绕残疾人、老年人、妇女、军人军属等特定群体，加大权益保护力度。 行政生效裁判监督是行政诉讼监督的重要职能之一。最高检于2024年10月部署开展行政生效裁判监督专项活动。 最高检有关负责人介绍，两年来，全国检察机关聚焦市场经营主体反映强烈的趋利性执法…"
