    "content": "快科技10月23日消息，当地时间10月22日，巴黎苏富比“施伦贝谢珍藏：追忆似水年华”专场拍卖上， 印象派大师莫奈晚年巨作《鸢尾花》以5000万欧元（含买家佣金，约合人民币3.74亿元）落槌，刷新本土成交纪录，成为法国拍卖史上价格最高的艺术品 。 这幅油画创作于1924至1925年，尺寸1.6米 x 1.8米，属于莫奈吉维尼花园系列晚期作品，与知名的《睡莲》同属一个创作阶段，笔触奔放、色彩朦胧，是莫奈视力衰退阶段极具代表性的作品。 它早在数十年前就被收藏家珍妮·施伦贝谢收入囊中，一直藏于施伦贝谢家族巴黎私宅，从未对…"
