    "author": "",
    "description": "新华社北京10月23日电（记者刘慧）10月23日，中国证监会发布关于核准设立花旗证券（中国）有限公司的批复，核准设立花旗证券（中国）有限公司。花旗证券（中国）有限公司注册地为上海市，注册资本为人民币12亿元，业务范围为证券经纪、证券投资咨询、证券承销与保荐、证券自营。",
    "content": "新华社北京10月23日电（记者刘慧）10月23日，中国证监会发布关于核准设立花旗证券（中国）有限公司的批复，核准设立花旗证券（中国）有限公司。花旗证券（中国）有限公司注册地为上海市，注册资本为人民币12亿元，业务范围为证券经纪、证券投资咨询、证券承销与保荐、证券自营。"
