    "content": "新华社首尔10月23日电（记者陈怡 姬新龙）韩国国防部政策室长金洪哲（音）23日发表谈话，正式向朝鲜提议举行韩朝军方会谈，就相互确认韩朝陆地军事分界线的准确位置、恢复军事通信线路以及防止边境地区发生意外冲突的方案进行协商。 谈话说，目前，韩朝双方对部分军事分界线位置的认知仍存在分歧。如不采取特别措施，双方官兵将继续以各自认定的军事分界线位置为基准开展活动，这将有可能导致意外冲突增加。 谈话还说，如有必要，也可以举行包括“联合国军司令部”在内的三方会谈。会谈具体日期和地点等事宜，可通过板门店渠道进行协商。期待朝方作出…"
