    "description": "中新网武汉10月23日电 (黄双子 史梦诗)华中科技大学国家脉冲强磁场科学中心李亮教授团队，联合法国巴黎高等物理化工学院学者，首次从热力学角度确认声子热霍尔效应源于材料内禀机制，而非杂质或缺陷导致的外在散射，为困扰学界21年的内禀—外禀之争提供了关键实验判据。",
    "content": "中新网武汉10月23日电 (黄双子 史梦诗)华中科技大学国家脉冲强磁场科学中心李亮教授团队，联合法国巴黎高等物理化工学院学者，首次从热力学角度确认声子热霍尔效应源于材料内禀机制，而非杂质或缺陷导致的外在散射，为困扰学界21年的内禀—外禀之争提供了关键实验判据。"
